const VERSION='lumora-iphone-v1',CORE=['/','/index.html','/style.css','/app.mjs','/engine.mjs','/gpu.mjs','/storage.mjs','/color-worker.mjs','/ai-worker.mjs','/manifest.webmanifest','/presets.json','/assets/logo.svg','/assets/icon-180.png','/assets/icon-192.png','/assets/icon-512.png','/assets/landscape.jpg','/assets/cutout-demo.jpg','/assets/desert.jpg','/assets/forest.jpg','/assets/botanical-garden.jpg','/assets/travertine-podium.jpg'];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(VERSION);for(const path of CORE){const response=await fetch(path,{credentials:'same-origin',cache:'reload'});if(!response.ok||response.redirected)throw Error('Offline setup needs a signed-in connection');await cache.put(path,response)}await self.skipWaiting()})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(let key of await caches.keys())if(key.startsWith('lumora-iphone-')&&key!==VERSION)await caches.delete(key);await self.clients.claim()})()));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||/signin|signout|callback/.test(url.pathname))return;if(event.request.mode==='navigate'){event.respondWith((async()=>{try{const r=await fetch(event.request);if(r.ok&&!r.redirected){const c=await caches.open(VERSION);await c.put('/index.html',r.clone())}return r}catch{return(await caches.match('/index.html'))||Response.error()}})());return}event.respondWith((async()=>{const cached=await caches.match(event.request);if(cached)return cached;const r=await fetch(event.request);if(r.ok&&!r.redirected){const c=await caches.open(VERSION);try{await c.put(event.request,r.clone())}catch{}}return r})())});
